/**
 * 智谱识别结果导出辅助脚本
 * 覆盖 handleWordExport 函数，在导出 Word 文档时包含智谱识别结果
 */
(function() {
    'use strict';
    
    // 从 DOM 中获取步骤数据
    function getStepsFromDOM() {
        var stepElements = document.querySelectorAll('#stepsList li');
        var steps = [];
    
        stepElements.forEach(function(li, index) {
            var textarea = li.querySelector('.step-title-input');
            var img = li.querySelector('img.step-image');
            var isTextOnly = li.classList.contains('step-text-only');
            var textContent = li.querySelector('.text-content');
            
            if (isTextOnly && textContent) {
                // 纯文本步骤
                steps.push({
                    type: 'text',
                    title: textarea ? textarea.value : ('第' + (index + 1) + '步'),
                    content: textContent.textContent,
                    timestamp: Date.now()
                });
            } else if (img && img.src) {
                // 图片步骤
                steps.push({
                    type: 'image',
                    title: textarea ? textarea.value : ('第' + (index + 1) + '步'),
                    screenshot: img.src,
                    timestamp: Date.now()
                });
            }
        });
            
        return steps;
    }
        
    // 解析Markdown为docx段落 - 现代简约风格
    function parseMarkdownToDocx(markdownText) {
        var paragraphs = [];
        var lines = markdownText.split('\n');
            
        for (var i = 0; i < lines.length; i++) {
            var line = lines[i];
                
            // 跳过空行
            if (!line.trim()) {
                paragraphs.push(new docx.Paragraph({ children: [] }));
                continue;
            }
                
            // 表格行检测 | col1 | col2 |
            if (line.includes('|') && line.trim().startsWith('|')) {
                var tableResult = parseTable(line, lines, i);
                if (tableResult.table) {
                    paragraphs.push(tableResult.table);
                    i += tableResult.consumedLines - 1;
                    continue;
                }
            }
                
            // 一级标题 # 标题 - 深蓝灰色主标题
            if (line.startsWith('# ')) {
                paragraphs.push(new docx.Paragraph({
                    children: [new docx.TextRun({
                        text: line.substring(2),
                        bold: true,
                        size: 28,
                        color: "2c3e50",
                        font: "Microsoft YaHei"
                    })],
                    spacing: { before: 240, after: 120 }
                }));
            }
            // 二级标题 ## 标题 - 深灰色副标题
            else if (line.startsWith('## ')) {
                paragraphs.push(new docx.Paragraph({
                    children: [new docx.TextRun({
                        text: line.substring(3),
                        bold: true,
                        size: 24,
                        color: "34495e",
                        font: "Microsoft YaHei"
                    })],
                    spacing: { before: 180, after: 100 }
                }));
            }
            // 三级标题 ### 标题 - 蓝色强调
            else if (line.startsWith('### ')) {
                paragraphs.push(new docx.Paragraph({
                    children: [new docx.TextRun({
                        text: line.substring(4),
                        bold: true,
                        size: 22,
                        color: "1a73e8",
                        font: "Microsoft YaHei"
                    })],
                    spacing: { before: 120, after: 80 }
                }));
            }
            // 无序列表项 - 优雅圆点
            else if (line.match(/^[\-\*]\s/)) {
                var itemText = line.replace(/^[\-\*]\s/, '');
                paragraphs.push(new docx.Paragraph({
                    children: [
                        new docx.TextRun({ text: "•  ", size: 19, color: "5f6368", font: "Microsoft YaHei" })
                    ].concat(parseInlineMarkdownRuns(itemText, 19, "3c4043")),
                    indent: { left: 400 },
                    spacing: { after: 60 }
                }));
            }
            // 有序列表项
            else if (line.match(/^\d+\.\s/)) {
                var match = line.match(/^(\d+\.)\s(.*)$/);
                if (match) {
                    paragraphs.push(new docx.Paragraph({
                        children: [
                            new docx.TextRun({ text: match[1] + "  ", size: 19, color: "5f6368", font: "Microsoft YaHei" })
                        ].concat(parseInlineMarkdownRuns(match[2], 19, "3c4043")),
                        indent: { left: 400 },
                        spacing: { after: 60 }
                    }));
                }
            }
            // 代码块 - 浅灰背景
            else if (line.startsWith('```')) {
                var codeLines = [];
                i++;
                while (i < lines.length && !lines[i].startsWith('```')) {
                    codeLines.push(lines[i]);
                    i++;
                }
                paragraphs.push(new docx.Paragraph({
                    children: [new docx.TextRun({
                        text: codeLines.join('\n'),
                        size: 17,
                        font: "Consolas",
                        color: "37474f"
                    })],
                    shading: { fill: "f8f9fa" },
                    indent: { left: 400 },
                    spacing: { before: 100, after: 100 }
                }));
            }
            // 引用块 > 文本 - 左侧边线
            else if (line.startsWith('> ')) {
                var quoteText = line.substring(2);
                paragraphs.push(new docx.Paragraph({
                    children: [new docx.TextRun({
                        text: quoteText,
                        size: 18,
                        color: "5f6368",
                        italics: true,
                        font: "Microsoft YaHei"
                    })],
                    indent: { left: 400 },
                    border: {
                        left: {
                            color: "dadce0",
                            size: 12,
                            space: 8,
                            style: "single"
                        }
                    },
                    spacing: { after: 60 }
                }));
            }
            // 普通段落 - 使用 rich runs 解析
            else {
                paragraphs.push(new docx.Paragraph({
                    children: parseInlineMarkdownRuns(line, 19, "3c4043"),
                    spacing: { after: 80 }
                }));
            }
        }
        
        return paragraphs;
    }
    
    // 解析内联Markdown - 返回 TextRun 数组以支持多种样式
    function parseInlineMarkdownRuns(text, baseSize, baseColor) {
        if (!text) return [new docx.TextRun({ text: '', size: baseSize, color: baseColor, font: "Microsoft YaHei" })];
        
        var runs = [];
        var remaining = text;
        var regex = /(\*\*\*([^*]+)\*\*\*|\*\*([^*]+)\*\*|\*([^*]+)\*|`([^`]+)`)/g;
        var lastIndex = 0;
        var match;
        
        while ((match = regex.exec(text)) !== null) {
            // 添加普通文本
            if (match.index > lastIndex) {
                runs.push(new docx.TextRun({
                    text: text.substring(lastIndex, match.index),
                    size: baseSize,
                    color: baseColor,
                    font: "Microsoft YaHei"
                }));
            }
            
            // 加粗+斜体 ***text***
            if (match[0].startsWith('***')) {
                runs.push(new docx.TextRun({
                    text: match[2],
                    bold: true,
                    italics: true,
                    size: baseSize,
                    color: baseColor,
                    font: "Microsoft YaHei"
                }));
            }
            // 加粗 **text**
            else if (match[0].startsWith('**')) {
                runs.push(new docx.TextRun({
                    text: match[3],
                    bold: true,
                    size: baseSize,
                    color: baseColor,
                    font: "Microsoft YaHei"
                }));
            }
            // 斜体 *text*
            else if (match[0].startsWith('*')) {
                runs.push(new docx.TextRun({
                    text: match[4],
                    italics: true,
                    size: baseSize,
                    color: baseColor,
                    font: "Microsoft YaHei"
                }));
            }
            // 行内代码 `code`
            else if (match[0].startsWith('`')) {
                runs.push(new docx.TextRun({
                    text: match[5],
                    font: "Consolas",
                    size: baseSize,
                    color: "37474f"
                }));
            }
            
            lastIndex = match.index + match[0].length;
        }
        
        // 添加剩余文本
        if (lastIndex < text.length) {
            runs.push(new docx.TextRun({
                text: text.substring(lastIndex),
                size: baseSize,
                color: baseColor,
                font: "Microsoft YaHei"
            }));
        }
        
        return runs.length > 0 ? runs : [new docx.TextRun({ text: text, size: baseSize, color: baseColor, font: "Microsoft YaHei" })];
    }
    
    // 解析内联Markdown - 简单版本，返回处理后的文本
    function parseInlineMarkdown(text) {
        if (!text) return text;
        // 移除行内代码标记
        text = text.replace(/`([^`]+)`/g, '$1');
        return text;
    }
    
    // 解析表格
    function parseTable(line, lines, startIndex) {
        var tableRows = [];
        var colCount = 0;
        
        // 表头行
        var headerCells = line.split('|').filter(function(c) { return c.trim(); });
        colCount = headerCells.length;
        
        var headerRow = new docx.TableRow({
            children: headerCells.map(function(cell) {
                return new docx.TableCell({
                    children: [new docx.Paragraph({
                        children: [new docx.TextRun({
                            text: cell.trim(),
                            bold: true,
                            size: 19,
                            color: "ffffff",
                            font: "Microsoft YaHei"
                        })]
                    })],
                    shading: { fill: "1a73e8" },
                    margins: { top: 80, bottom: 80, left: 120, right: 120 }
                });
            })
        });
        tableRows.push(headerRow);
        
        // 跳过分隔线
        var dataIndex = startIndex + 1;
        if (dataIndex < lines.length && lines[dataIndex].match(/^[|:\-\s]+$/)) {
            dataIndex++;
        }
        
        // 数据行
        while (dataIndex < lines.length) {
            var dataLine = lines[dataIndex];
            if (!dataLine.trim() || !dataLine.includes('|')) break;
            
            var dataCells = dataLine.split('|').filter(function(c) { return c.trim(); });
            if (dataCells.length === 0) break;
            
            var dataRow = new docx.TableRow({
                children: dataCells.map(function(cell) {
                    return new docx.TableCell({
                        children: [new docx.Paragraph({
                            children: [new docx.TextRun({
                                text: cell.trim(),
                                size: 18,
                                color: "3c4043",
                                font: "Microsoft YaHei"
                            })]
                        })],
                        margins: { top: 60, bottom: 60, left: 120, right: 120 }
                    });
                })
            });
            tableRows.push(dataRow);
            dataIndex++;
        }
        
        return {
            table: new docx.Table({
                rows: tableRows,
                width: { size: 100, type: docx.WidthType.PERCENTAGE }
            }),
            consumedLines: dataIndex - startIndex
        };
    }
    
    // 等待 DOM 加载完成
    function initZhipuExport() {
        // 等待 docx 库和 handleWordExport 函数加载
        var checkInterval = setInterval(function() {
            if (typeof docx !== 'undefined' && typeof window.handleWordExport === 'function') {
                clearInterval(checkInterval);
                overrideWordExport();
            }
        }, 100);
        
        // 最多等待 10 秒
        setTimeout(function() {
            clearInterval(checkInterval);
        }, 10000);
    }
    
    function overrideWordExport() {
        // 保存原始函数引用
        var originalHandleWordExport = window.handleWordExport;
        
        // 覆盖 handleWordExport
        window.handleWordExport = async function() {
            try {
                // 读取文档设置
                var docConfig = await new Promise(function(resolve) {
                    chrome.storage.sync.get(['docConfig'], function(result) {
                        resolve(result.docConfig || {
                            title: '操作步骤',
                            showInfo: true,
                            showTime: true,
                            showFooter: true,
                            footerText: '本文档由 AI 自动生成'
                        });
                    });
                });
                
                // 从 DOM 获取步骤数据
                var steps = getStepsFromDOM();
                
                if (!steps || steps.length === 0) {
                    alert("没有可导出的步骤");
                    return;
                }
                
                if (typeof docx === 'undefined') {
                    throw new Error("docx库未加载");
                }
                
                // 获取识别结果
                var recognitionResults = await new Promise(function(resolve) {
                    chrome.storage.local.get(['zhipuRecognitionResults'], function(result) {
                        resolve(result.zhipuRecognitionResults || {});
                    });
                });
                
                var a = new Date();
                var filename = docConfig.title + '_' + 
                    a.getFullYear() + 
                    String(a.getMonth() + 1).padStart(2, '0') + 
                    String(a.getDate()).padStart(2, '0') + '_' + 
                    String(a.getHours()).padStart(2, '0') + 
                    String(a.getMinutes()).padStart(2, '0') + 
                    String(a.getSeconds()).padStart(2, '0') + 
                    '.docx';
                
                var n = [];
                
                // ========== 封面区域 ==========
                // 添加分页，让封面单独一页
                n.push(new docx.Paragraph({
                    children: [],
                    pageBreakBefore: true
                }));
                
                // 顶部留白
                n.push(new docx.Paragraph({
                    children: [],
                    spacing: { before: 800 }
                }));
                
                // 主标题 - 居中大标题
                n.push(new docx.Paragraph({
                    children: [new docx.TextRun({
                        text: docConfig.title || '操作步骤文档',
                        bold: true,
                        size: 60,
                        color: "1a73e8",
                        font: "Microsoft YaHei"
                    })],
                    alignment: docx.AlignmentType.CENTER,
                    spacing: { before: 200, after: 300 }
                }));
                
                // 副标题
                n.push(new docx.Paragraph({
                    children: [new docx.TextRun({
                        text: '详细操作指南',
                        size: 32,
                        color: "5f6368",
                        font: "Microsoft YaHei"
                    })],
                    alignment: docx.AlignmentType.CENTER,
                    spacing: { after: 400 }
                }));
                
                // 描述文字
                n.push(new docx.Paragraph({
                    children: [new docx.TextRun({
                        text: '规范操作步骤，确保流程清晰',
                        size: 22,
                        color: "7f8c8d",
                        font: "Microsoft YaHei"
                    })],
                    alignment: docx.AlignmentType.CENTER,
                    spacing: { after: 800 }
                }));
                
                // 蓝色分隔线
                n.push(new docx.Paragraph({
                    children: [],
                    border: {
                        bottom: {
                            color: "1a73e8",
                            size: 24,
                            space: 1,
                            style: "single"
                        }
                    },
                    alignment: docx.AlignmentType.CENTER,
                    spacing: { after: 800 }
                }));
                
                // 信息卡片 - 居中显示
                if (docConfig.showInfo) {
                    // 步骤数量卡片
                    n.push(new docx.Paragraph({
                        children: [new docx.TextRun({
                            text: '📋 共 ' + steps.length + ' 个操作步骤',
                            bold: true,
                            size: 24,
                            color: "2c3e50",
                            font: "Microsoft YaHei"
                        })],
                        alignment: docx.AlignmentType.CENTER,
                        spacing: { before: 400, after: 200 }
                    }));
                    
                    // 生成时间
                    n.push(new docx.Paragraph({
                        children: [new docx.TextRun({
                            text: '📅 ' + new Date().toLocaleDateString("zh-CN"),
                            size: 20,
                            color: "5f6368",
                            font: "Microsoft YaHei"
                        })],
                        alignment: docx.AlignmentType.CENTER,
                        spacing: { after: 800 }
                    }));
                }
                
                // 底部信息
                n.push(new docx.Paragraph({
                    children: [new docx.TextRun({
                        text: '━━━━━━━━━━━━━━━━━━━━',
                        size: 18,
                        color: "bdc3c7",
                        font: "Microsoft YaHei"
                    })],
                    alignment: docx.AlignmentType.CENTER,
                    spacing: { before: 600, after: 200 }
                }));
                
                // 技术支持中心
                n.push(new docx.Paragraph({
                    children: [new docx.TextRun({
                        text: '技术支持中心',
                        size: 20,
                        color: "5f6368",
                        font: "Microsoft YaHei"
                    })],
                    alignment: docx.AlignmentType.CENTER,
                    spacing: { after: 100 }
                }));
                
                // 版权年份
                n.push(new docx.Paragraph({
                    children: [new docx.TextRun({
                        text: '© ' + new Date().getFullYear() + ' 版权所有',
                        size: 16,
                        color: "95a5a6",
                        font: "Microsoft YaHei"
                    })],
                    alignment: docx.AlignmentType.CENTER,
                    spacing: { after: 400 }
                }));
                
                // 分页进入内容区域
                n.push(new docx.Paragraph({
                    children: [],
                    pageBreakBefore: true
                }));
                
                // ========== 步骤区域 ==========
                for (var t = 0; t < steps.length; t++) {
                    var o = steps[t];
                    
                    // 步骤描述
                    n.push(new docx.Paragraph({
                        children: [
                            new docx.TextRun({
                                text: o.title || '',
                                bold: true,
                                size: 24,
                                color: "2c3e50",
                                font: "Microsoft YaHei"
                            })
                        ],
                        spacing: { before: 300, after: 150 }
                    }));
                    
                    if (o.type === 'text') {
                        // 纯文本步骤 - 直接显示文本内容
                        n.push(new docx.Paragraph({
                            children: [new docx.TextRun({
                                text: '📝 文本步骤',
                                bold: true,
                                size: 16,
                                color: "667eea",
                                font: "Microsoft YaHei"
                            })],
                            spacing: { before: 80, after: 60 }
                        }));
                        
                        n.push(new docx.Paragraph({
                            children: [new docx.TextRun({
                                text: o.content || '',
                                size: 18,
                                color: "3c4043",
                                font: "Microsoft YaHei"
                            })],
                            spacing: { after: 150 }
                        }));
                        
                        // 检查是否有 AI 扩写结果
                        if (recognitionResults && recognitionResults['text_expanded']) {
                            n.push(new docx.Paragraph({
                                children: [new docx.TextRun({
                                    text: '✨ AI 扩写结果',
                                    bold: true,
                                    size: 18,
                                    color: "2c3e50",
                                    font: "Microsoft YaHei"
                                })],
                                spacing: { before: 100, after: 80 }
                            }));
                            
                            var mdParagraphs = parseMarkdownToDocx(recognitionResults['text_expanded']);
                            for (var mi = 0; mi < mdParagraphs.length; mi++) {
                                n.push(mdParagraphs[mi]);
                            }
                        }
                    } else {
                        // 图片步骤
                        try {
                            var imageType = "png";
                            if (o.screenshot.includes("data:image/jpeg") || o.screenshot.includes("data:image/jpg")) {
                                imageType = "jpeg";
                            } else if (o.screenshot.includes("data:image/png")) {
                                imageType = "png";
                            } else if (o.screenshot.includes("data:image/gif")) {
                                imageType = "gif";
                            } else if (o.screenshot.includes("data:image/bmp")) {
                                imageType = "bmp";
                            }
                            
                            var imageData = o.screenshot.split(",")[1];
                            var imageBytes = Uint8Array.from(atob(imageData), function(e) {
                                return e.charCodeAt(0);
                            });
                            
                            var img = new Image();
                            img.src = o.screenshot;
                            
                            await new Promise(function(resolve, reject) {
                                img.onload = resolve;
                                img.onerror = reject;
                                setTimeout(reject, 5000);
                            });
                            
                            var scale = 1;
                            var imgWidth = img.naturalWidth;
                            var imgHeight = img.naturalHeight;
                            
                            if (imgWidth > 600) {
                                scale = 600 / imgWidth;
                                imgWidth = 600;
                                imgHeight = Math.round(imgHeight * scale);
                            }
                            
                            n.push(new docx.Paragraph({
                                children: [new docx.ImageRun({
                                    data: imageBytes,
                                    transformation: {
                                        width: imgWidth,
                                        height: imgHeight
                                    },
                                    type: imageType
                                })],
                                alignment: docx.AlignmentType.CENTER,
                                spacing: { after: 150 }
                            }));
                        } catch (e) {
                            n.push(new docx.Paragraph({
                                children: [new docx.TextRun({
                                    text: "[图片加载失败]",
                                    italics: true,
                                    color: "e74c3c",
                                    font: "Microsoft YaHei"
                                })],
                                alignment: docx.AlignmentType.CENTER,
                                spacing: { after: 150 }
                            }));
                        }
                        
                        // 智谱识别结果 - 带边框卡片
                        if (recognitionResults && recognitionResults[t] !== undefined) {
                            // 识别结果标题
                            n.push(new docx.Paragraph({
                                children: [new docx.TextRun({
                                    text: '📝 AI 分析结果',
                                    bold: true,
                                    size: 18,
                                    color: "2c3e50",
                                    font: "Microsoft YaHei"
                                })],
                                spacing: { before: 100, after: 80 }
                            }));
                            
                            // 解析Markdown格式的识别结果
                            var mdParagraphs = parseMarkdownToDocx(recognitionResults[t]);
                            for (var mi = 0; mi < mdParagraphs.length; mi++) {
                                n.push(mdParagraphs[mi]);
                            }
                        }
                    }
                    
                    // 时间戳
                    if (docConfig.showTime) {
                        n.push(new docx.Paragraph({
                            children: [new docx.TextRun({
                                text: '⏱️ ' + new Date(o.timestamp).toLocaleString("zh-CN"),
                                size: 16,
                                color: "95a5a6",
                                font: "Microsoft YaHei"
                            })],
                            spacing: { after: 200 }
                        }));
                    }
                }
                
                // ========== 页脚区域 ==========
                if (docConfig.showFooter) {
                    // 分隔线
                    n.push(new docx.Paragraph({
                        children: [],
                        border: {
                            top: {
                                color: "bdc3c7",
                                size: 8,
                                space: 8,
                                style: "single"
                            }
                        },
                        spacing: { before: 400, after: 200 }
                    }));
                    
                    // 页脚公司信息
                    n.push(new docx.Paragraph({
                        children: [new docx.TextRun({
                            text: '技术支持中心',
                            bold: true,
                            size: 18,
                            color: "2c3e50",
                            font: "Microsoft YaHei"
                        })],
                        alignment: docx.AlignmentType.CENTER,
                        spacing: { after: 60 }
                    }));
                    
                    // 版权信息
                    n.push(new docx.Paragraph({
                        children: [new docx.TextRun({
                            text: '© ' + new Date().getFullYear() + ' 版权所有',
                            size: 16,
                            color: "7f8c8d",
                            font: "Microsoft YaHei"
                        })],
                        alignment: docx.AlignmentType.CENTER,
                        spacing: { after: 100 }
                    }));
                }
                
                // 生成文档
                var doc = new docx.Document({
                    sections: [{
                        properties: {
                            page: {
                                margin: {
                                    top: 1440,
                                    right: 1440,
                                    bottom: 1440,
                                    left: 1440
                                }
                            }
                        },
                        children: n
                    }]
                });
                
                var blob = await docx.Packer.toBlob(doc);
                
                var reader = new FileReader();
                reader.onload = function() {
                    chrome.runtime.sendMessage({
                        action: "downloadFile",
                        data: {
                            dataUrl: reader.result,
                            filename: filename
                        }
                    });
                };
                reader.readAsDataURL(blob);
                
            } catch (e) {
                alert("导出Word文档失败: " + e.message);
            }
        };
    }
    
    // DOM 加载完成后初始化
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initZhipuExport);
    } else {
        initZhipuExport();
    }
})();
